const block = (prefix, number) => `${prefix}-${number}`;
const heading = (number, text) => ({ id: block("heading", number), type: "heading", level: 2, text });
const paragraph = (number, text) => ({ id: block("paragraph", number), type: "paragraph", text });
const tip = (number, title, body) => ({ id: block("tip", number), type: "tip", label: "CURATED TIP", title, body });
const idea = (number, [title, body, budget, bestFor, setting]) => ({
  id: block("idea", number), type: "idea", eyebrow: "PARTY IDEA", title, body, image: "", imageAlt: "", budget, bestFor, setting,
});
const table = (title, rows) => ({ id: "table-1", type: "table", title, headers: ["Decision", "Simple option", "Make it feel special"], rows });
const checklist = (items) => ({ id: "checklist-1", type: "checklist", title: "Your practical planning checklist", items });
const internalLink = (number, [title, body, anchor, slug]) => ({
  id: block("internal", number), type: "internal_link", eyebrow: "KEEP PLANNING", title, body, anchor, url: `/article/${slug}`,
});
const faq = (items) => ({ id: "faq-1", type: "faq", title: "Frequently asked questions", items: items.map(([question, answer]) => ({ question, answer })) });

function buildArticle(config) {
  if (config.ideas.length !== 12) throw new Error(`${config.slug} must contain exactly 12 original ideas.`);
  const hero = `/pinterest/growth-${config.slug}.png`;
  const planner = config.categoryPath.endsWith("teen-birthdays")
    ? ["Teen Birthday Planner + Games Pack", "/shop/teen-birthday-party-planner", "$14"]
    : ["Ultimate Birthday Party Planner", "/shop/ultimate-birthday-party-planner", "$12"];

  return {
    slug: config.slug,
    categoryPath: config.categoryPath,
    title: config.title,
    dek: config.dek,
    readTime: "12 min read",
    seoTitle: config.title,
    seoDescription: config.seoDescription,
    image: hero,
    imageAlt: config.imageAlt,
    socialImage: hero,
    blocks: [
      heading(1, config.openingHeading),
      paragraph(1, config.introduction),
      tip(1, config.tipTitle, config.tipBody),
      heading(2, config.sections[0]),
      ...config.ideas.slice(0, 4).map((entry, index) => idea(index + 1, entry)),
      heading(3, config.sections[1]),
      ...config.ideas.slice(4, 8).map((entry, index) => idea(index + 5, entry)),
      heading(4, config.sections[2]),
      ...config.ideas.slice(8, 12).map((entry, index) => idea(index + 9, entry)),
      heading(5, "Turn the inspiration into a realistic party plan"),
      table(config.tableTitle, config.tableRows),
      checklist(config.checklist),
      {
        id: "product-1", type: "product_cta", eyebrow: "THE CURATED PIN SHOP", title: planner[0],
        body: "Keep the guest list, budget, shopping, activities and party-day timing together in one reusable printable planner.",
        cta: "See the planner", url: planner[1], price: planner[2], image: "", imageAlt: "",
      },
      ...config.links.map((entry, index) => internalLink(index + 1, entry)),
      faq(config.faqs),
    ],
  };
}

